window.getEmailDraftContent = function(data) {
    const cliente = (data.cliente || '').trim().toUpperCase();
    const tipo = (data.tipoSolicitud || 'REPUESTO').toUpperCase();
    let subject = "";

    if (tipo === 'NOTA DE CREDITO' || tipo === 'NOTA_CREDITO') {
        const equipo = (data.producto || data.modelo || 'EQUIPO').trim().toUpperCase();
        subject = "SOLICITUD NOTA DE CREDITO GARANTIA " + cliente + " Y " + equipo;
    } else if (tipo === 'CAMBIO DE EQUIPO' || tipo === 'CAMBIO_EQUIPO' || tipo === 'CAMBIO DE PRODUCTO') {
        const equipo = (data.producto || data.modelo || 'EQUIPO').trim().toUpperCase();
        subject = "SOLICITUD CAMBIO DE PRODUCTO GARANTIA " + cliente + " Y " + equipo;
    } else {
        const repuesto = (data.descRepuesto || data.codRepuesto || 'REPUESTO').trim().toUpperCase();
        subject = "SOLICITUD REPUESTO GARANTIA " + cliente + " Y " + repuesto;
    }

    // Envio vacio sin texto en el cuerpo
    const body = "";
    return { subject: subject, body: body, tipo: tipo };
};

