// Helper robusto para obtener visitas desde cualquier fuente en memoria
function getAllVisits() {
    if (typeof window.getVisitsArray === 'function') {
        const arr = window.getVisitsArray();
        if (arr && arr.length) return arr;
    }
    if (window.visitsArray && window.visitsArray.length) {
        return window.visitsArray;
    }
    return [];
}

// Rellenar opciones del selector de visitas/clientes
function renderVisitsSelectorOptions(selectedId = null) {
    const sel = document.getElementById('solicitud_visit_selector');
    if (!sel) return;
    const visits = getAllVisits();
    
    // Priorizar garantias y visitas recientes
    const options = ['<option value="">-- SELECCIONAR CLIENTE DE LA AGENDA / HISTORIAL --</option>'];
    visits.forEach(v => {
        const isGar = (v.tipoAtencion === 'Garantía' || v.estado === 'Garantia en Tramite');
        const badge = isGar ? '🛡️ [GARANTÍA] ' : '';
        const eq = (v.equipos && v.equipos[0]?.descProducto) || v.asunto || '';
        const isSel = (String(v.id) === String(selectedId)) ? 'selected' : '';
        options.push(`<option value="${v.id}" ${isSel}>${badge}${v.nombreCliente || 'SIN NOMBRE'} • ${eq} • ${v.fechaInstalacion || ''}</option>`);
    });
    sel.innerHTML = options.join('');
    if (selectedId) sel.value = selectedId;
}

// Autocompletar formulario a partir de la visita
window.autoFillSolicitudFromVisit = function(visitId) {
    if (!visitId) return;
    const visits = getAllVisits();
    const v = visits.find(item => String(item.id) === String(visitId));
    if (!v) {
        console.warn('Visita no encontrada para autofill:', visitId);
        return;
    }

    const eq = (v.equipos && v.equipos.length > 0) ? v.equipos[0] : {};

    // Obtener valores en vivo de los inputs de la tarjeta de garantía si existen en el DOM
    const liveCodRep = document.getElementById('garantias_cod_repuesto_' + visitId)?.value;
    const liveDescRep = document.getElementById('garantias_desc_repuesto_' + visitId)?.value;
    const liveObs = document.getElementById('garantias_obs_' + visitId)?.value;

    const clienteEl = document.getElementById('solicitud_cliente');
    const telEl = document.getElementById('solicitud_telefono');
    const ciudadEl = document.getElementById('solicitud_ciudad');
    const dirEl = document.getElementById('solicitud_direccion');
    const lugarEl = document.getElementById('solicitud_lugar_compra');
    const fechaCompEl = document.getElementById('solicitud_fecha_compra');
    const factEl = document.getElementById('solicitud_num_factura');
    const prodEl = document.getElementById('solicitud_producto');
    const modEl = document.getElementById('solicitud_modelo');
    const serieEl = document.getElementById('solicitud_serie');
    const codProdEl = document.getElementById('solicitud_cod_producto');
    const diagEl = document.getElementById('solicitud_diagnostico');
    const codRepEl = document.getElementById('solicitud_cod_repuesto');
    const descRepEl = document.getElementById('solicitud_desc_repuesto');
    const selVisit = document.getElementById('solicitud_visit_selector');
    const tipoSelect = document.getElementById('solicitud_tipo');

    if (selVisit) selVisit.value = visitId;
    if (clienteEl) clienteEl.value = (v.nombreCliente || '').toUpperCase();
    if (telEl) telEl.value = v.telefono || '';
    if (ciudadEl) ciudadEl.value = 'Cuenca';
    if (dirEl) dirEl.value = (v.callePrincipal || 'Cuenca').toUpperCase();
    if (lugarEl) lugarEl.value = (v.lugarCompra || 'SUKASA').toUpperCase();
    if (fechaCompEl) fechaCompEl.value = formatFechaCompra(v.fechaEmision || '');
    if (factEl) factEl.value = (v.numFactura || '').toUpperCase();

    // Detección automática de tipo de trámite
    let targetTipo = 'REPUESTO';
    if (v.tramiteGarantiaTipo === 'NOTA_CREDITO' || v.tramiteGarantiaTipo === 'NOTA DE CREDITO' || isClienteNotaCreditoOCambio(v.nombreCliente)) {
        targetTipo = 'NOTA DE CREDITO';
    } else if (v.tramiteGarantiaTipo === 'CAMBIO_EQUIPO' || v.tramiteGarantiaTipo === 'CAMBIO DE EQUIPO') {
        targetTipo = 'CAMBIO DE EQUIPO';
    }

    if (tipoSelect) {
        tipoSelect.value = targetTipo;
        toggleTipoSolicitudUI(targetTipo);
    }

    // Producto y Modelo
    let catDesc = (eq.codProducto && window.CATALOGO_TEKA_BASE && window.CATALOGO_TEKA_BASE[eq.codProducto]) || '';
    let prodName = (eq.descProducto || v.tipoAtencion || 'ENCIMERA').toUpperCase();
    let modelName = (catDesc || eq.manualName || eq.descProducto || '').toUpperCase();

    // Si modelName es muy corto (ej: "SS", "INOX") o no contiene el tipo de producto
    if (prodName && modelName && !modelName.includes(prodName)) {
        if (modelName.length <= 15 || modelName === 'SS' || modelName.startsWith('SS')) {
            modelName = (prodName + ' ' + modelName).trim();
        }
    }
    if (!prodName && modelName) prodName = modelName;

    if (prodEl) prodEl.value = prodName;
    if (modEl) modEl.value = modelName;
    if (serieEl) serieEl.value = (eq.serieEquipo || '').toUpperCase();
    if (codProdEl) codProdEl.value = (eq.codProducto || '').toUpperCase();

    // Diagnostico / Observaciones
    const finalObs = (liveObs && liveObs.trim()) ? liveObs.trim() : (v.observacionGarantia || v.commentarioCliente || v.razonNoAtencion || v.observacionesAdmin || '');
    if (diagEl) diagEl.value = finalObs.toUpperCase();

    // Repuesto o Resolución
    if (targetTipo === 'REPUESTO') {
        let finalCodRep = (liveCodRep && liveCodRep.trim()) ? liveCodRep.trim() : (eq.codRepuesto || '');
        let finalDescRep = (liveDescRep && liveDescRep.trim()) ? liveDescRep.trim() : (eq.descRepuesto || '');
        if (!finalCodRep && v.repuestoSolicitadoGarantia) {
            const parts = v.repuestoSolicitadoGarantia.split(' - ');
            finalCodRep = parts[0] ? parts[0].trim() : '';
            finalDescRep = parts[1] ? parts[1].trim() : '';
        }
        if (codRepEl) codRepEl.value = finalCodRep.toUpperCase();
        if (descRepEl) descRepEl.value = finalDescRep.toUpperCase();
    } else if (targetTipo === 'NOTA DE CREDITO') {
        if (codRepEl) codRepEl.value = 'NOTA DE CRÉDITO';
        if (descRepEl) descRepEl.value = 'SE SOLICITA NOTA DE CRÉDITO POR EQUIPO IRREPARABLE';
    } else if (targetTipo === 'CAMBIO DE EQUIPO') {
        if (codRepEl) codRepEl.value = 'CAMBIO DE EQUIPO';
        if (descRepEl) descRepEl.value = 'SE SOLICITA CAMBIO DE PRODUCTO/EQUIPO POR NO DISPONIBILIDAD DE REPARACIÓN';
    }

    if (window.showMessage) {
        if (targetTipo === 'NOTA DE CREDITO') {
            window.showMessage('💡 ' + (v.nombreCliente || 'Cliente') + ': Configurado para NOTA DE CRÉDITO (Solo Formato Word)', 'fix-report');
        } else if (targetTipo === 'CAMBIO DE EQUIPO') {
            window.showMessage('💡 ' + (v.nombreCliente || 'Cliente') + ': Configurado para CAMBIO DE EQUIPO (Solo Formato Word)', 'fix-report');
        } else {
            window.showMessage('✅ Datos de ' + (v.nombreCliente || 'cliente') + ' autocompletados', 'fix-report');
        }
    }
};

