// Manejo de carga de archivos (Factura y Orden Manual)
window.handleSolicitudFileUpload = async function(event, type) {
    const file = event.target.files[0];
    if (!file) return;

    if (file.size > 10 * 1024 * 1024) {
        if (window.showMessage) window.showMessage('⚠️ El archivo no debe superar los 10MB', 'fix-accent');
        return;
    }

    const reader = new FileReader();
    reader.onload = function(e) {
        const fileObj = {
            name: file.name,
            type: file.type,
            size: file.size,
            data: e.target.result,
            uploadedAt: Date.now()
        };

        if (type === 'factura') {
            window.tempFacturaFile = fileObj;
            updateFilePreviewUI('solicitudFacturaPreview', fileObj, 'Factura');
        } else if (type === 'orden') {
            window.tempOrdenFile = fileObj;
            updateFilePreviewUI('solicitudOrdenPreview', fileObj, 'Orden');
        }
        if (window.showMessage) window.showMessage('📎 Archivo cargado correctamente', 'fix-report');
    };
    reader.readAsDataURL(file);
};

function updateFilePreviewUI(containerId, fileObj, label) {
    const el = document.getElementById(containerId);
    if (!el) return;
    if (!fileObj) {
        el.innerHTML = '<span class="text-[10px] text-stone-400 font-bold">Sin archivo adjunto</span>';
        return;
    }

    const isPdf = fileObj.type === 'application/pdf' || fileObj.name.toLowerCase().endsWith('.pdf');
    const icon = isPdf ? '📄' : '🖼️';
    el.innerHTML = `
        <div class="flex items-center justify-between p-2 rounded-xl bg-blue-50 border border-blue-200">
            <div class="flex items-center gap-2 overflow-hidden">
                <span class="text-base">${icon}</span>
                <div class="truncate">
                    <p class="text-[10px] font-black text-blue-950 truncate">${fileObj.name}</p>
                    <p class="text-[8px] text-blue-700 font-bold">${label} adjuntada (${Math.round((fileObj.size || 0)/1024)} KB)</p>
                </div>
            </div>
            <div class="flex items-center gap-1.5 shrink-0">
                <button type="button" onclick="previewOrDownloadFile('${containerId}')" class="px-2 py-1 bg-blue-600 text-white rounded-lg text-[9px] font-black uppercase hover:bg-blue-700">Ver</button>
                <button type="button" onclick="removeAttachment('${containerId}')" class="px-2 py-1 bg-rose-600 text-white rounded-lg text-[9px] font-black uppercase hover:bg-rose-700">✕</button>
            </div>
        </div>
    `;
}

window.removeAttachment = function(containerId) {
    if (containerId === 'solicitudFacturaPreview') window.tempFacturaFile = null;
    if (containerId === 'solicitudOrdenPreview') window.tempOrdenFile = null;
    updateFilePreviewUI(containerId, null, '');
};

window.previewOrDownloadFile = function(containerId) {
    const fileObj = containerId === 'solicitudFacturaPreview' ? window.tempFacturaFile : window.tempOrdenFile;
    if (!fileObj || !fileObj.data) return;

    if (fileObj.type && fileObj.type.startsWith('image/')) {
        openMediaModal(fileObj.data, fileObj.name);
    } else {
        const a = document.createElement('a');
        a.href = fileObj.data;
        a.download = fileObj.name;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
    }
};

