// Guardar solicitud en Firebase
window.saveSolicitudGarantiaForm = function() {
    const numInput = document.getElementById('solicitud_numero').value.trim();
    const clienteInput = document.getElementById('solicitud_cliente').value.trim().toUpperCase();
    const codRepInput = document.getElementById('solicitud_cod_repuesto').value.trim().toUpperCase();
    const descRepInput = document.getElementById('solicitud_desc_repuesto').value.trim().toUpperCase();
    const tipoInput = document.getElementById('solicitud_tipo')?.value || 'REPUESTO';

    if (!numInput || !clienteInput) {
        if (window.showMessage) window.showMessage('⚠️ Ingrese el N° de solicitud y el nombre del cliente', 'fix-error');
        return;
    }

    let seq = 70;
    const m = numInput.match(/(\d+)/);
    if (m) seq = parseInt(m[1], 10);

    const solicitudObj = {
        numeroSolicitud: numInput,
        numeroSecuencia: seq,
        tipoSolicitud: tipoInput,
        fechaEnvio: document.getElementById('solicitud_fecha_envio').value || new Date().toISOString().split('T')[0],
        visitId: document.getElementById('solicitud_visit_selector').value || '',
        cliente: clienteInput,
        telefono: document.getElementById('solicitud_telefono').value.trim(),
        ciudad: document.getElementById('solicitud_ciudad').value.trim() || 'Cuenca',
        direccion: document.getElementById('solicitud_direccion').value.trim().toUpperCase(),
        lugarCompra: document.getElementById('solicitud_lugar_compra').value.trim().toUpperCase(),
        fechaCompra: document.getElementById('solicitud_fecha_compra').value.trim(),
        numFactura: document.getElementById('solicitud_num_factura').value.trim().toUpperCase(),
        producto: document.getElementById('solicitud_producto').value.trim().toUpperCase(),
        modelo: document.getElementById('solicitud_modelo').value.trim().toUpperCase(),
        serie: document.getElementById('solicitud_serie').value.trim().toUpperCase(),
        codProducto: document.getElementById('solicitud_cod_producto').value.trim().toUpperCase(),
        diagnostico: document.getElementById('solicitud_diagnostico').value.trim().toUpperCase(),
        codRepuesto: codRepInput,
        descRepuesto: descRepInput,
        estado: document.getElementById('solicitud_estado').value || 'SOLICITADO',
        facturaFile: window.tempFacturaFile || null,
        ordenFile: window.tempOrdenFile || null,
        updatedAt: Date.now()
    };

    const id = window.currentSolicitudEditId;
    let promise;
    if (id) {
        promise = database.ref('solicitudes_garantia/' + id).update(solicitudObj);
    } else {
        solicitudObj.createdAt = Date.now();
        const ref = database.ref('solicitudes_garantia').push();
        solicitudObj.id = ref.key;
        promise = ref.set(solicitudObj);
    }

    promise.then(() => {
        // Sincronizar estado de la visita vinculada si existe
        if (solicitudObj.visitId && typeof database !== 'undefined') {
            let vTipo = 'REPUESTO';
            if (tipoInput === 'NOTA DE CREDITO') vTipo = 'NOTA_CREDITO';
            else if (tipoInput === 'CAMBIO DE EQUIPO') vTipo = 'CAMBIO_EQUIPO';
            database.ref('visits/' + solicitudObj.visitId).update({
                tramiteGarantiaTipo: vTipo,
                repuestoSolicitadoGarantia: (tipoInput === 'REPUESTO') ? (codRepInput ? `${codRepInput} - ${descRepInput}` : 'REPUESTO') : tipoInput
            }).catch(e => console.warn('Sync visit error:', e));
        }

        if (window.showMessage) window.showMessage('💾 Solicitud archivada exitosamente', 'fix-report');
        closeSolicitudGarantiaModal();
        renderSolicitudesGarantiaView();
    }).catch(err => {
        console.error('Error guardando solicitud:', err);
        if (window.showMessage) window.showMessage('❌ Error al guardar: ' + err.message, 'fix-error');
    });
};

