// ==========================================================================
// 5. RENDERIZADO DE LA VISTA PRINCIPAL
// ==========================================================================
window.renderSolicitudesGarantiaView = function() {
    const listContainer = document.getElementById('solicitudesTableBody');
    if (!listContainer) return;

    const query = (document.getElementById('solicitudesSearchInput')?.value || '').trim().toUpperCase();
    const filterEstado = document.getElementById('solicitudesEstadoFilter')?.value || 'TODOS';
    const filterTipo = document.getElementById('solicitudesTipoFilter')?.value || 'TODOS';

    let list = window.solicitudesGarantiaArray || [];

    // Filtros
    if (filterEstado !== 'TODOS') {
        list = list.filter(s => s.estado === filterEstado);
    }
    if (filterTipo !== 'TODOS') {
        list = list.filter(s => (s.tipoSolicitud || 'REPUESTO') === filterTipo);
    }
    if (query) {
        list = list.filter(s => 
            (s.cliente && s.cliente.toUpperCase().includes(query)) ||
            (s.numeroSolicitud && s.numeroSolicitud.toUpperCase().includes(query)) ||
            (s.producto && s.producto.toUpperCase().includes(query)) ||
            (s.serie && s.serie.toUpperCase().includes(query)) ||
            (s.codRepuesto && s.codRepuesto.toUpperCase().includes(query)) ||
            (s.tipoSolicitud && s.tipoSolicitud.toUpperCase().includes(query))
        );
    }

    // Actualizar KPIs
    const all = window.solicitudesGarantiaArray || [];
    const kpiTotal = all.length;
    const kpiSolicitados = all.filter(s => s.estado === 'SOLICITADO').length;
    const kpiEnviados = all.filter(s => s.estado === 'ENVIADO A FÁBRICA').length;
    const kpiRecibidos = all.filter(s => s.estado === 'REPUESTO RECIBIDO' || s.estado === 'AUTORIZADO').length;
    const kpiCerrados = all.filter(s => s.estado === 'INSTALADO / CERRADO').length;

    const elKpiTotal = document.getElementById('solicitudesKpiTotal');
    const elKpiSol = document.getElementById('solicitudesKpiSolicitados');
    const elKpiEnv = document.getElementById('solicitudesKpiEnviados');
    const elKpiRec = document.getElementById('solicitudesKpiRecibidos');
    const elKpiCer = document.getElementById('solicitudesKpiCerrados');
    const elNextBadge = document.getElementById('solicitudesNextNumBadge');

    if (elKpiTotal) elKpiTotal.textContent = kpiTotal;
    if (elKpiSol) elKpiSol.textContent = kpiSolicitados;
    if (elKpiEnv) elKpiEnv.textContent = kpiEnviados;
    if (elKpiRec) elKpiRec.textContent = kpiRecibidos;
    if (elKpiCer) elKpiCer.textContent = kpiCerrados;
    if (elNextBadge) {
        const next = getNextSolicitudNumero();
        elNextBadge.textContent = 'PRÓXIMA: N° ' + next.numeroSolicitud;
    }

    if (list.length === 0) {
        listContainer.innerHTML = `<tr><td colspan="9" class="p-12 text-center text-stone-400 font-black uppercase italic">No hay solicitudes registradas con estos filtros</td></tr>`;
        return;
    }

    listContainer.innerHTML = list.map(s => {
        // Badges de estado
        let badgeColor = 'bg-amber-100 text-amber-900 border-amber-300';
        if (s.estado === 'ENVIADO A FÁBRICA') badgeColor = 'bg-blue-100 text-blue-900 border-blue-300';
        if (s.estado === 'REPUESTO RECIBIDO' || s.estado === 'AUTORIZADO') badgeColor = 'bg-purple-100 text-purple-900 border-purple-300';
        if (s.estado === 'INSTALADO / CERRADO') badgeColor = 'bg-emerald-100 text-emerald-900 border-emerald-300';

        // Badge de Tipo
        const tipo = (s.tipoSolicitud || 'REPUESTO').toUpperCase();
        let tipoBadgeHtml = `<span class="px-2 py-0.5 rounded text-[8px] font-black uppercase bg-amber-100 text-amber-900 border border-amber-300">📦 Repuesto</span>`;
        if (tipo === 'NOTA DE CREDITO' || tipo === 'NOTA_CREDITO') {
            tipoBadgeHtml = `<span class="px-2 py-0.5 rounded text-[8px] font-black uppercase bg-rose-100 text-rose-900 border border-rose-300">💳 Nota Crédito</span>`;
        } else if (tipo === 'CAMBIO DE EQUIPO' || tipo === 'CAMBIO_EQUIPO' || tipo === 'CAMBIO DE PRODUCTO') {
            tipoBadgeHtml = `<span class="px-2 py-0.5 rounded text-[8px] font-black uppercase bg-indigo-100 text-indigo-900 border border-indigo-300">🔄 Cambio Producto</span>`;
        }

        const hasFactura = s.facturaFile && s.facturaFile.data;
        const hasOrden = s.ordenFile && s.ordenFile.data;
        const isWordOnly = (tipo === 'NOTA DE CREDITO' || tipo === 'NOTA_CREDITO' || tipo === 'CAMBIO DE EQUIPO' || tipo === 'CAMBIO_EQUIPO' || tipo === 'CAMBIO DE PRODUCTO');

        return `
            <tr class="border-b border-stone-200/70 hover:bg-indigo-50/40 transition-colors font-medium text-xs text-stone-800">
                <td class="p-3.5 text-center font-mono font-black text-indigo-900">
                    <span class="px-2.5 py-1 rounded-lg bg-indigo-100 text-indigo-950 border border-indigo-200 block mb-1">${s.numeroSolicitud || '---'}</span>
                    ${tipoBadgeHtml}
                </td>
                <td class="p-3.5 font-mono text-[11px] text-stone-600 whitespace-nowrap">
                    ${s.fechaEnvio || '---'}
                </td>
                <td class="p-3.5">
                    <p class="font-black text-fix-main uppercase text-xs">${s.cliente || '---'}</p>
                    <p class="text-[10px] text-stone-500 font-mono">📞 ${s.telefono || '---'} • 📍 ${s.ciudad || 'Cuenca'}</p>
                </td>
                <td class="p-3.5">
                    <p class="font-bold uppercase text-[11px] text-stone-900">${s.producto || '---'}</p>
                    <p class="text-[9px] text-stone-500 font-mono">MOD: ${s.modelo || '-'} | SERIE: ${s.serie || '-'}</p>
                </td>
                <td class="p-3.5">
                    <p class="font-mono font-black text-[11px] text-amber-950">${s.codRepuesto || '---'}</p>
                    <p class="text-[10px] font-bold text-stone-600 uppercase">${s.descRepuesto || '---'}</p>
                </td>
                <td class="p-3.5 text-center">
                    <select onchange="updateSolicitudEstado('${s.id}', this.value)" class="p-1.5 rounded-lg text-[10px] font-black uppercase border ${badgeColor} shadow-2xs outline-none cursor-pointer">
                        <option value="SOLICITADO" ${s.estado === 'SOLICITADO' ? 'selected' : ''}>⏳ SOLICITADO / ESPERA</option>
                        <option value="ENVIADO A FÁBRICA" ${s.estado === 'ENVIADO A FÁBRICA' ? 'selected' : ''}>📤 ENVIADO A FÁBRICA</option>
                        <option value="REPUESTO RECIBIDO" ${s.estado === 'REPUESTO RECIBIDO' ? 'selected' : ''}>📦 RECIBIDO / EN MANO</option>
                        <option value="AUTORIZADO" ${s.estado === 'AUTORIZADO' ? 'selected' : ''}>💳 NOTA AUTORIZADA</option>
                        <option value="INSTALADO / CERRADO" ${s.estado === 'INSTALADO / CERRADO' ? 'selected' : ''}>✅ INSTALADO / CERRADO</option>
                    </select>
                </td>
                <td class="p-3.5 text-center whitespace-nowrap">
                    <div class="flex items-center justify-center gap-1.5">
                        <button type="button" onclick="downloadAttachmentFromList('${s.id}', 'factura')" class="px-2 py-1 rounded-lg text-[9px] font-black uppercase transition-all ${hasFactura ? 'bg-blue-600 hover:bg-blue-700 text-white shadow-xs' : 'bg-slate-100 hover:bg-blue-100 text-slate-600 hover:text-blue-700 border border-dashed border-slate-300 hover:border-blue-400 cursor-pointer active:scale-95'}" title="${hasFactura ? 'Ver Factura' : 'Sin Factura registrada. Clic para cargarla'}">
                            ${hasFactura ? '🧾 Factura' : '➕ Cargar Fact.'}
                        </button>
                        <button type="button" onclick="downloadAttachmentFromList('${s.id}', 'orden')" class="px-2 py-1 rounded-lg text-[9px] font-black uppercase transition-all ${hasOrden ? 'bg-amber-600 hover:bg-amber-700 text-white shadow-xs' : 'bg-slate-100 hover:bg-amber-100 text-slate-600 hover:text-amber-700 border border-dashed border-slate-300 hover:border-amber-400 cursor-pointer active:scale-95'}" title="${hasOrden ? 'Ver Orden Manual' : 'Sin Orden registrada. Clic para cargarla'}">
                            ${hasOrden ? '📋 Orden' : '➕ Cargar Ord.'}
                        </button>
                    </div>
                </td>
                <td class="p-3.5 text-center whitespace-nowrap">
                    <div class="flex items-center justify-center gap-1">
                        <!-- DESCARGA WORD EXACTO -->
                        <button type="button" onclick="downloadSolicitudWordFromList('${s.id}')" class="p-2 bg-blue-700 hover:bg-blue-800 text-white rounded-xl text-xs font-black uppercase shadow-xs transition-all active:scale-95" title="Descargar Formato Word Oficial (.docx)">
                            📄 Word
                        </button>
                        <!-- DESCARGA EXCEL EXACTO (SOLO SI APLICA REPUESTO) -->
                        ${isWordOnly ? `
                            <span class="p-2 bg-stone-100 text-stone-400 border border-stone-200 rounded-xl text-[10px] font-bold uppercase select-none" title="No aplica Excel para Nota de Crédito o Cambio">
                                🚫 Sin Excel
                            </span>
                        ` : `
                            <button type="button" onclick="downloadSolicitudExcelFromList('${s.id}')" class="p-2 bg-emerald-700 hover:bg-emerald-800 text-white rounded-xl text-xs font-black uppercase shadow-xs transition-all active:scale-95" title="Descargar Excel Exacto (.xlsx)">
                                📊 Excel
                            </button>
                        `}
                        <!-- CORREO PREPARADO -->
                        <button type="button" onclick="openEmailModal('${s.id}')" class="p-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl text-xs font-black uppercase shadow-xs transition-all active:scale-95" title="Preparar Correo para Srta. Marcia">
                            ✉️
                        </button>
                        <!-- EDITAR -->
                        <button type="button" onclick="openEditSolicitudModal('${s.id}')" class="p-2 bg-stone-200 hover:bg-stone-300 text-stone-700 rounded-xl text-xs font-black shadow-xs transition-all" title="Editar Expediente">
                            ✏️
                        </button>
                        <!-- ELIMINAR -->
                        <button type="button" onclick="deleteSolicitudGarantia('${s.id}')" class="p-2 bg-rose-100 hover:bg-rose-200 text-rose-700 rounded-xl text-xs font-black shadow-xs transition-all" title="Eliminar">
                            🗑️
                        </button>
                    </div>
                </td>
            </tr>
        `;
    }).join('');
};
